SELECT i.exchange,i.exchange_symbol,i.base_asset,i.quote_asset,i.settle_asset,i.contract_multiplier,m.canonical_market_key,m.canonical_base_asset,m.canonical_base_units_per_venue_base_unit,f.* FROM crypto_market_info_perp_soak.funding_rate_hourly AS f FINAL INNER JOIN crypto_market_info_perp_soak.instrument AS i FINAL USING(instrument_id) INNER JOIN (SELECT * FROM crypto_market_info_perp_soak.instrument_canonical_mapping FINAL ORDER BY recorded_at DESC LIMIT 1 BY instrument_id) m USING(instrument_id) ORDER BY instrument_id,hour_time
